import boto3
from botocore.exceptions import ClientError


def _merge_intervals(intervals):
    if not intervals:
        return []

    sorted_intervals = sorted(intervals, key=lambda x: x['begin_offset'])
    merged = [sorted_intervals[0]]

    for current in sorted_intervals[1:]:
        last = merged[-1]
        if current['begin_offset'] <= last['end_offset']:
            last['end_offset'] = max(last['end_offset'], current['end_offset'])
            last['labels'] = list(set(last['labels']) | set(current['labels']))
            last['max_score'] = max(last['max_score'], current['max_score'])
        else:
            merged.append(current)

    return merged


def moderate_and_redact_text(text, region_name="us-east-1", toxicity_threshold=0.5):
    client = boto3.client('comprehend', region_name=region_name)

    try:
        response = client.detect_toxic_content(
            TextSegments=[{"Text": text}],
            LanguageCode='en'
        )
    except ClientError as e:
        raise RuntimeError(f"AWS Comprehend API error: {e}") from e

    matches = response['ResultList'][0]['Matches']
    flagged_spans = []

    for match in matches:
        toxicity = match['Toxicity']
        if toxicity['Score'] >= toxicity_threshold:
            flagged_spans.append({
                "begin_offset": match['BeginOffset'],
                "end_offset": match['EndOffset'],
                "max_score": toxicity['Score'],
                "labels": [match['Type']]
            })

    merged_spans = _merge_intervals(flagged_spans)

    redacted_text = text
    for span in sorted(merged_spans, key=lambda x: x['begin_offset'], reverse=True):
        redacted_text = (
            redacted_text[:span['begin_offset']] +
            "[REDACTED]" +
            redacted_text[span['end_offset']:]
        )

    return {
        "flagged_spans": merged_spans,
        "redacted_text": redacted_text
    }
